package es.aelb.backendweb.infrastructure.email;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import es.aelb.backendweb.application.email.*; import es.aelb.backendweb.infrastructure.config.EmailProperties; import es.aelb.backendweb.infrastructure.persistence.jpa.entity.EmailOutboxJpaEntity; import es.aelb.backendweb.infrastructure.observability.ObservabilityMetrics; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import org.slf4j.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.time.*; import java.util.*; import java.util.concurrent.Executor;
@Component public class EmailWorker {
 private static final Logger log=LoggerFactory.getLogger(EmailWorker.class); private final EmailSender sender; private final EmailPayloadCrypto crypto; private final EmailProperties props; private final ObjectMapper mapper; private final EmailRateLimiter limiter; private final EmailOutboxTransactionService transactions; private final Executor executor; private final ObservabilityMetrics metrics;
 @org.springframework.beans.factory.annotation.Autowired public EmailWorker(EmailSender sender,EmailPayloadCrypto crypto,EmailProperties props,ObjectMapper mapper,EmailRateLimiter limiter,EmailOutboxTransactionService transactions,@org.springframework.beans.factory.annotation.Qualifier("emailWorkerExecutor") Executor executor, ObservabilityMetrics metrics){this.sender=sender;this.crypto=crypto;this.props=props;this.mapper=mapper;this.limiter=limiter;this.transactions=transactions;this.executor=executor;this.metrics=metrics;}
 public EmailWorker(EmailSender sender,EmailPayloadCrypto crypto,EmailProperties props,ObjectMapper mapper,EmailRateLimiter limiter,EmailOutboxTransactionService transactions,Executor executor){this(sender,crypto,props,mapper,limiter,transactions,executor,new ObservabilityMetrics(new SimpleMeterRegistry()));}
 @Scheduled(fixedDelayString="${aelb.email.worker-delay-ms:100}") public void tick(){if(!props.isEnabled()||!props.isWorkerEnabled())return; transactions.recover(); List<EmailOutboxJpaEntity> jobs=transactions.claim(); for(EmailOutboxJpaEntity job:jobs) executor.execute(() -> process(job));}
 @Scheduled(fixedDelay=600000) public void clean(){if(props.isEnabled()&&props.isWorkerEnabled())transactions.cleanSent();}
 private void process(EmailOutboxJpaEntity job){if(!limiter.tryAcquire()){requeue(job,"rate limit",LocalDateTime.now().plusNanos(500_000_000));return;} try{Map<String,String> p=mapper.readValue(crypto.decrypt(job.getPayload()),new TypeReference<>(){});EmailMessage m=render(job.getType(),job.getRecipient(),p);sender.send(m);markSent(job);}catch(PermanentEmailException e){markFailed(job,e.getMessage());}catch(Exception e){retry(job,e);}}
 protected void markSent(EmailOutboxJpaEntity j){transactions.sent(j);metrics.email("sent");log.info("event=EMAIL_SENT emailJobId={} type={} attempt={}",j.getId(),j.getType(),j.getAttempts()+1);}
 protected void requeue(EmailOutboxJpaEntity j,String error,LocalDateTime next){transactions.pending(j,error,next);}
 protected void retry(EmailOutboxJpaEntity j,Exception error){int attempts=j.getAttempts()+1;if(attempts>=props.getMaxRetries()){markFailed(j,error.getMessage());return;}long base=(long)Math.min(3600,Math.pow(5,attempts-1)*60);long jitter=Math.abs(new Random().nextLong(30));transactions.retry(j,safe(error.getMessage()),attempts,LocalDateTime.now().plusSeconds(base+jitter));metrics.email("retried");log.warn("event=EMAIL_RETRIED emailJobId={} type={} attempt={} error={}",j.getId(),j.getType(),attempts,safe(error.getMessage()));}
 protected void markFailed(EmailOutboxJpaEntity j,String error){transactions.failed(j,safe(error));metrics.email("failed");log.error("event=EMAIL_FAILED emailJobId={} type={} attempts={} error={}",j.getId(),j.getType(),j.getAttempts()+1,safe(error));}
 private String safe(String s){return s==null?"email error":s.substring(0,Math.min(1000,s.length()));}
 private EmailMessage render(EmailType type,String to,Map<String,String> p){String name=p.getOrDefault("name","");String site=props.getFrontendPublicUrl();AelbEmailTemplate.Content c=switch(type){
  case PASSWORD_RESET->new AelbEmailTemplate.Content("Recupera tu contraseña","Seguridad de la cuenta","Recupera tu contraseña",name,List.of("Hemos recibido una solicitud para restablecer la contraseña de tu cuenta en la plataforma de la AELB.","Pulsa el botón para elegir una nueva contraseña."),List.of(),"Restablecer contraseña",site+"/reset-password?token="+p.get("token"),"El enlace caduca en "+props.getPasswordResetTokenExpirationMinutes()+" minutos. Si no has solicitado este cambio, ignora este correo: tu contraseña seguirá siendo la misma.");
  case EMAIL_VERIFICATION->new AelbEmailTemplate.Content("Verifica tu email","Bienvenida","Verifica tu dirección de email",name,List.of("Gracias por registrarte en la plataforma de la Asociación Española de Lucha de Brazos.","Confirma tu dirección de email para activar tu cuenta y poder inscribirte en campeonatos."),List.of(),"Verificar email",site+"/verify-email?token="+p.get("token"),"El enlace caduca en "+props.getEmailVerificationTokenExpirationHours()+" horas. Si no has creado ninguna cuenta, ignora este correo.");
  case REGISTRATION_CONFIRMATION->new AelbEmailTemplate.Content("Inscripción confirmada","Campeonatos","Inscripción confirmada",name,List.of("Tu inscripción ha quedado registrada correctamente. ¡Nos vemos en la mesa!"),List.of(new AelbEmailTemplate.Detail("Campeonato",p.getOrDefault("championship",""))),"Ver campeonatos",site+"/campeonatos",null);
  default->new AelbEmailTemplate.Content("Pago confirmado","Pagos","Pago confirmado",name,List.of("Hemos recibido tu pago correctamente. Guarda este correo como justificante."),List.of(new AelbEmailTemplate.Detail("Concepto",p.getOrDefault("description","")),new AelbEmailTemplate.Detail("Importe",p.getOrDefault("amount",""))),"Ir a mi perfil",site+"/perfil",null);
 };return new AelbEmailTemplate(site).render(to,c);}
}
